int main() {
    std::map<std::string, int> counts;
    std::istringstream in("b a b c a b");
    std::string w;
    while (in >> w) ++counts[w];
    bool first = true;
    for (const auto& [k, v] : counts) {
        std::cout << (first ? "" : " ") << k << "=" << v;
        first = false;
    }
    std::cout << "\n";

    std::vector<int> v{1, 3, 5, 7};
    std::cout << (std::lower_bound(v.begin(), v.end(), 4) - v.begin()) << " "
              << (std::upper_bound(v.begin(), v.end(), 5) - v.begin()) << " "
              << std::binary_search(v.begin(), v.end(), 7) << "\n";

    std::priority_queue<int> pq;
    for (int x : {3, 1, 4, 1, 5}) pq.push(x);
    first = true;
    while (!pq.empty()) {
        std::cout << (first ? "" : " ") << pq.top();
        pq.pop();
        first = false;
    }
    std::cout << "\n";
    return 0;
}

