class Buf {
    int* d_;
    std::size_t n_;
public:
    explicit Buf(std::size_t n) : d_(new int[n]()), n_(n) {}
    Buf(const Buf& o) : d_(new int[o.n_]), n_(o.n_) { std::copy(o.d_, o.d_ + n_, d_); }
    Buf(Buf&& o) noexcept : d_(o.d_), n_(o.n_) { o.d_ = nullptr; o.n_ = 0; }
    Buf& operator=(Buf o) noexcept { std::swap(d_, o.d_); std::swap(n_, o.n_); return *this; }
