int counter = 0;
std::mutex mtx;

void work() {
    for (int i = 0; i < 1000; ++i) {
        std::lock_guard<std::mutex> lk(mtx);
        ++counter;
    }
}

int main() {
    std::vector<std::thread> ts;
    for (int i = 0; i < 4; ++i) ts.emplace_back(work);
    for (auto& t : ts) t.join();
    std::cout << counter << "\n";

    int a = 100, b = 100;
    std::mutex ma, mb;
    std::thread t1([&] {
        for (int i = 0; i < 100; ++i) {
            std::scoped_lock lk(ma, mb);
            a -= 10; b += 10;
        }
    });
    std::thread t2([&] {
        for (int i = 0; i < 100; ++i) {
            std::scoped_lock lk(mb, ma);
            b -= 5; a += 5;
        }
    });
    t1.join(); t2.join();
    std::cout << a << " " << b << "\n";

    std::vector<long> part(4, 0);
    std::vector<std::thread> ws;
    for (int k = 0; k < 4; ++k)
        ws.emplace_back([&part, k] {
            for (int x = k * 25 + 1; x <= (k + 1) * 25; ++x) part[k] += x;
        });
    for (auto& t : ws) t.join();
    long total = 0;
    for (long p : part) total += p;
    std::cout << total << "\n";
    return 0;
}

