#include <atomic>
#include <iostream>
#include <thread>
#include <vector>

void updateMax(std::atomic<int>& m, int v) {
    int cur = m.load();
    while (cur < v && !m.compare_exchange_weak(cur, v)) {}
}

int main() {
    std::atomic<int> counter{0};
    std::vector<std::thread> ts;
    for (int i = 0; i < 4; ++i)
        ts.emplace_back([&] { for (int j = 0; j < 1000; ++j) counter.fetch_add(1); });
    for (auto& t : ts) t.join();
    std::cout << counter.load() << "\n";

    std::atomic<int> x{5};
    int old = x.fetch_add(3);
    std::cout << old << " " << x.load() << "\n";

    std::atomic<int> mx{0};
    std::vector<std::thread> us;
    for (int v : {5, 9, 3, 7}) us.emplace_back(updateMax, std::ref(mx), v);
    for (auto& t : us) t.join();
    std::cout << mx.load() << "\n";

    int data = 0;
    std::atomic<bool> ready{false};
    std::thread producer([&] {
        data = 42;
        ready.store(true, std::memory_order_release);
    });
    while (!ready.load(std::memory_order_acquire)) std::this_thread::yield();
    std::cout << data << "\n";
    producer.join();
    return 0;
}

