    float f = 1.0f;
    std::uint32_t u;
    std::memcpy(&u, &f, sizeof u);
    std::cout << std::hex << u << std::dec << "\n";

    std::cout << std::boolalpha << addOverflows(INT_MAX, 1) << "\n";
    std::cout << addOverflows(1, 2) << "\n";

