#include <iostream>
#include <list>
#include <unordered_map>
#include <utility>

class LRU {
    std::size_t cap_;
    std::list<std::pair<int, int>> items_;  // front = most recent
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> idx_;
public:
    explicit LRU(std::size_t cap) : cap_(cap) {}
    int get(int key) {
        auto it = idx_.find(key);
        if (it == idx_.end()) return -1;
        items_.splice(items_.begin(), items_, it->second);
        return it->second->second;
    }
    void put(int key, int value) {
        auto it = idx_.find(key);
        if (it != idx_.end()) {
            it->second->second = value;
            items_.splice(items_.begin(), items_, it->second);
            return;
        }
        if (items_.size() == cap_) {
            idx_.erase(items_.back().first);
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        idx_[key] = items_.begin();
    }
};

int main() {
    LRU c(2);
    c.put(1, 10);
    c.put(2, 20);
    std::cout << c.get(1) << "\n";
    c.put(3, 30);
    std::cout << c.get(2) << "\n";
    std::cout << c.get(3) << "\n";
    return 0;
}
